package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// crdtOpIn is one element of a CRDT submission. Exactly one content shape is
// meaningful depending on the declared document type: value for a counter,
// elements for a grow-only set, value plus version for a register, action
// plus element for an observed-remove set.
type crdtOpIn struct {
	ID       string          `json:"id"`
	Value    json.RawMessage `json:"value"`
	Elements []string        `json:"elements"`
	Version  json.RawMessage `json:"version"`
	Action   string          `json:"action"`
	Element  string          `json:"element"`
}

// crdtOpsRequest is the body of POST .../crdt/ops.
type crdtOpsRequest struct {
	DeviceID string     `json:"deviceId"`
	Type     string     `json:"type"`
	Ops      []crdtOpIn `json:"ops"`
}

// sessionCRDTOpsRequest is the body of the session-scoped POST .../crdt/ops:
// the document-level shape minus the device id, which the session supplies.
type sessionCRDTOpsRequest struct {
	Type string     `json:"type"`
	Ops  []crdtOpIn `json:"ops"`
}

// handleCRDTOps accepts a batch of CRDT operations for a document.
//
// The batch declares the document's type; the first accepted batch fixes it
// to counter, gset, register or orset and every later batch must declare the
// same type. Two batches racing to declare different types serialize in one
// transaction: exactly one takes effect and the other is a 409 that writes
// nothing.
//
// The strict body contract matches the other JSON endpoints: application/json,
// one JSON value, no trailing content, a non-empty deviceId, a valid type, a
// non-empty ops array of elements with non-empty ids, no in-batch duplicate
// ids, and type-correct content (counter: an integer value; gset: an elements
// array; register: any JSON value — null included — plus a non-negative
// integer version; orset: action "add" or "remove" plus a non-empty string
// element). Any violation is a 400 with zero writes.
func handleCRDTOps(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req crdtOpsRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	ops, ok := decodeCRDTOps(w, req.Type, req.Ops)
	if !ok {
		return
	}
	for i := range ops {
		ops[i].DeviceID = req.DeviceID
	}

	results, err := s.SubmitCRDTOps(documentID, req.Type, ops)
	if err != nil {
		var conflict *crdt.ErrConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, conflict.Error())
		default:
			writeError(w, http.StatusInternalServerError, "failed to commit crdt ops")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

// handleSessionCRDTOps is the session-scoped CRDT batch commit:
//
//	POST /v1/sessions/{sessionId}/documents/{documentId}/crdt/ops
//
// The request body carries only the declared type and the ops array — the
// calling device is the session's owning device, resolved with the same
// identity rule as the session reads and subscriptions; no new credential is
// introduced and no device id travels in the body. Type fixation, the four
// merge rules, per-op idempotency and conflict judgments, the success body
// (results in request order, each naming its id and whether it was created)
// and the state-change push are exactly the document-level submission's: both
// handlers funnel into the same serialized commit. The checks run in the
// fixed order request shape (400), session existence (404), document
// permission (403, taken inside the commit transaction) and only then the
// state-dependent judgments (409). Every rejection — a malformed body, an
// empty or duplicate-id batch, a missing or deleted session, a revoked
// permission, a type conflict, a regressed contribution or version — writes
// nothing and notifies nobody.
func handleSessionCRDTOps(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	var req sessionCRDTOpsRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	// Request shape is settled before the session lookup, so a malformed batch
	// against an unknown session is still a 400. The device is stamped onto
	// the ops only after the session resolves.
	ops, ok := decodeCRDTOps(w, req.Type, req.Ops)
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	for i := range ops {
		ops[i].DeviceID = deviceID
	}

	results, err := s.SubmitCRDTOps(documentID, req.Type, ops)
	if err != nil {
		var conflict *crdt.ErrConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			// The session's device was deregistered between the lookup and the
			// commit; its cascade removed the session too, so the identity the
			// caller used no longer exists.
			writeError(w, http.StatusNotFound, "session not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, conflict.Error())
		default:
			writeError(w, http.StatusInternalServerError, "failed to commit crdt ops")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

// decodeCRDTOps validates the shared type/ops contract of a CRDT submission
// and builds the service-level operations (without a device stamp; the caller
// supplies the device identity). Any violation writes a 400 and reports
// false: an unknown type, an empty ops array, an element with a missing or
// empty id, an in-batch duplicate id, or type-incorrect content (counter: an
// integer value >= 0; gset: a non-empty elements array of non-empty strings;
// register: any JSON value — null included — plus a non-negative integer
// version; orset: action "add" or "remove" plus a non-empty string element).
func decodeCRDTOps(w http.ResponseWriter, declaredType string, in []crdtOpIn) ([]crdt.Op, bool) {
	if declaredType != crdt.TypeCounter && declaredType != crdt.TypeGSet && declaredType != crdt.TypeRegister && declaredType != crdt.TypeORSet {
		writeError(w, http.StatusBadRequest, `type must be "counter", "gset", "register" or "orset"`)
		return nil, false
	}
	if len(in) == 0 {
		writeError(w, http.StatusBadRequest, "ops must be a non-empty array")
		return nil, false
	}

	ops := make([]crdt.Op, len(in))
	seen := make(map[string]struct{}, len(in))
	for i, op := range in {
		if op.ID == "" {
			writeError(w, http.StatusBadRequest, "each op must have a non-empty string id")
			return nil, false
		}
		if _, dup := seen[op.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate op id within batch: "+op.ID)
			return nil, false
		}
		seen[op.ID] = struct{}{}

		crdtOp := crdt.Op{ID: op.ID}
		switch declaredType {
		case crdt.TypeCounter:
			v, ok := parseNonNegativeInt(op.Value)
			if !ok {
				writeError(w, http.StatusBadRequest, "each counter op must carry an integer value >= 0")
				return nil, false
			}
			// Re-marshal the canonical integer so idempotency compares the
			// decoded value rather than the client's literal formatting.
			raw, _ := json.Marshal(v)
			crdtOp.Value = raw
		case crdt.TypeGSet:
			if len(op.Elements) == 0 {
				writeError(w, http.StatusBadRequest, "each gset op must add at least one element")
				return nil, false
			}
			for _, element := range op.Elements {
				if element == "" {
					writeError(w, http.StatusBadRequest, "gset elements must be non-empty strings")
					return nil, false
				}
			}
			crdtOp.Elements = op.Elements
		case crdt.TypeRegister:
			// The value may be any JSON, null included; only an absent field
			// (a nil RawMessage — an explicit null decodes to the bytes
			// "null") is a missing field. The value is stored verbatim.
			if op.Value == nil {
				writeError(w, http.StatusBadRequest, "each register op must carry a value")
				return nil, false
			}
			v, ok := parseNonNegativeInt(op.Version)
			if !ok {
				writeError(w, http.StatusBadRequest, "each register op must carry an integer version >= 0")
				return nil, false
			}
			crdtOp.Value = op.Value
			crdtOp.Version = v
		case crdt.TypeORSet:
			if op.Action != crdt.ORSetAdd && op.Action != crdt.ORSetRemove {
				writeError(w, http.StatusBadRequest, `each orset op must carry action "add" or "remove"`)
				return nil, false
			}
			if op.Element == "" {
				writeError(w, http.StatusBadRequest, "each orset op must carry a non-empty string element")
				return nil, false
			}
			crdtOp.Action = op.Action
			crdtOp.Element = op.Element
		}
		ops[i] = crdtOp
	}
	return ops, true
}

// handleCRDTState returns the document's current type and merged result. A
// document with no committed operations has no state yet and answers 404.
func handleCRDTState(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	state, err := s.GetCRDTState(documentID)
	if err != nil {
		if errors.Is(err, crdt.ErrNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt state")
		return
	}

	writeCRDTState(w, state)
}

// handleSessionCRDTState is the session-scoped view of the document-level
// state read:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state
//
// The read identity is entirely the existing session (no new auth): the
// session's owning device is the credential and the validation order matches
// the other session-scoped reads exactly — request shape (400, enforced by the
// route and path guard before this handler), then session existence
// (404 JSON for a session that never existed or was deleted), then the
// session device's permission for the document (403 JSON with no state
// content), and finally the document's CRDT state. A document without any
// committed CRDT operation is the same 404 JSON as the document-level read, so
// a deleted session, an unknown document-state and a revoked permission remain
// three independent answers.
//
// On success the body is byte-for-byte the document-level state read's body
// (writeCRDTState): compact single-line JSON, keys type then value, one
// trailing newline. The endpoint is read-only: it renders the state derived by
// the store without advancing a cursor, writing a change, registering a
// subscription or affecting CRDT type fixation, idempotency or persistence; a
// restart changes neither the answer nor the status codes.
func handleSessionCRDTState(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	state, err := s.GetCRDTState(documentID)
	if err != nil {
		if errors.Is(err, crdt.ErrNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt state")
		return
	}

	writeCRDTState(w, state)
}

// writeCRDTState renders a CRDT state exactly as every state reader must:
// compact single-line JSON with the keys in type, value order, terminated by a
// newline (the json.Encoder output), shared by the document-level read, the
// session-scoped read and — via marshalCRDTState — the subscription push
// frames, so the three can be compared byte-for-byte.
func writeCRDTState(w http.ResponseWriter, state crdt.State) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(marshalCRDTState(state))
}

// marshalCRDTState encodes a CRDT state the single way every surface emits it:
// compact single-line JSON with the keys in type, value order and one trailing
// newline. The value is embedded as native JSON (a number, an array, or a
// register's arbitrary JSON value) rather than an escaped blob.
func marshalCRDTState(state crdt.State) []byte {
	var buf strings.Builder
	enc := json.NewEncoder(&buf)
	_ = enc.Encode(map[string]any{
		"type":  state.Type,
		"value": json.RawMessage(state.Value),
	})
	return []byte(buf.String())
}

// malformedCRDTPath reports whether p targets the CRDT namespace but is not at
// one of the five exact endpoints:
//
//	POST     /v1/documents/{documentID}/crdt/ops
//	GET      /v1/documents/{documentID}/crdt/state
//	POST     /v1/documents/{documentID}/crdt/compact
//	GET      /v1/documents/{documentID}/crdt/snapshot
//	GET      /v1/documents/{documentID}/crdt/state/subscribe
//
// A missing/empty document id, a trailing slash, extra path segments, or a
// "crdt" segment in any position short of that shape is a malformed 400 rather
// than ServeMux's redirect or plain-text 404/405, so the new endpoints never
// redirect or emit HTML. The keyword is matched only past the documentID
// position, so a document literally named "crdt" keeps its ordinary routes.
func malformedCRDTPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg == "crdt" && i > 0 {
			if segs[0] == "" {
				return true
			}
			// The CRDT state subscription adds one trailing "subscribe"
			// segment past the state read; nothing else may follow state.
			if len(segs) == 4 && segs[2] == "state" && segs[3] == "subscribe" {
				return false
			}
			if len(segs) != 3 {
				return true
			}
			switch segs[2] {
			case "ops", "state", "compact", "snapshot":
				return false
			default:
				return true
			}
		}
	}
	return false
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// changeLookupRequest is the body of POST .../changes/query: the calling
// device and the non-empty, in-batch-unique set of change ids to answer. The
// device identity uses the same declaration the document-level change commit
// uses — no new authentication is introduced.
type changeLookupRequest struct {
	DeviceID string   `json:"deviceId"`
	IDs      []string `json:"ids"`
}

// changeLookupItem fixes the on-the-wire key order of one answer to id,
// status, then (for a found row) deviceId, payload and cursor. The
// device/payload/cursor fields are omitted entirely on missing and compacted
// answers: a compacted id reports only its first cursor, so it carries
// cursor alone alongside id and status, and a missing id carries nothing but
// its id and status.
type changeLookupItem struct {
	ID       string          `json:"id"`
	Status   string          `json:"status"`
	DeviceID string          `json:"deviceId,omitempty"`
	Payload  json.RawMessage `json:"payload,omitempty"`
	Cursor   int64           `json:"cursor,omitempty"`
}

// changeLookupResponse is the query body with the top-level key order fixed
// to results then count; count always equals the number of result entries,
// which equals the number of ids asked for.
type changeLookupResponse struct {
	Results []changeLookupItem `json:"results"`
	Count   int                `json:"count"`
}

// handleQueryChanges is the read-only batch lookup over a document's change
// collection:
//
//	POST /v1/documents/{documentID}/changes/query
//
// The strict application/json body names the calling device and a non-empty
// array of non-empty, in-batch-unique change ids; answers arrive in the exact
// order the ids were given. Each id is answered independently:
//
//   - "found": the change is still in the online log, so the answer carries
//     its originating device, the payload verbatim as it was saved at commit
//     time and its first cursor;
//   - "compacted": compaction trimmed the row, so the answer reports only the
//     first cursor held in its retained summary — no payload is restored and
//     the summary never participates in an ordinary read;
//   - "missing": the id has never belonged to the document, so the answer
//     carries no content. A missing id is a normal answer, not an error.
//
// The verdict order is request shape (400) first — content type, JSON
// validity, trailing content, a missing or empty ids array, an empty or
// mistyped element and an in-batch duplicate — then device existence (404)
// and document permission (403). A 404 or 403 exposes no change content. The
// query creates no change, allocates no cursor and wakes neither a long poll
// nor a push subscriber. Success is one compact JSON line ending in a
// newline with results then count.
func handleQueryChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req changeLookupRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	// Shape checks all precede the device existence verdict, so a malformed
	// query against an unregistered device is still a 400.
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	// A missing (nil) or empty ids array is the same request-shape error; a
	// non-string element was already rejected while decoding the JSON.
	if len(req.IDs) == 0 {
		writeError(w, http.StatusBadRequest, "ids must be a non-empty array of non-empty strings")
		return
	}
	seen := make(map[string]struct{}, len(req.IDs))
	for _, id := range req.IDs {
		if id == "" {
			writeError(w, http.StatusBadRequest, "each id must be a non-empty string")
			return
		}
		if _, dup := seen[id]; dup {
			writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+id)
			return
		}
		seen[id] = struct{}{}
	}

	lookups, err := s.GetChangesByIDs(documentID, req.DeviceID, req.IDs)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		default:
			writeError(w, http.StatusInternalServerError, "failed to look up changes")
		}
		return
	}

	items := make([]changeLookupItem, len(lookups))
	for i, l := range lookups {
		items[i] = changeLookupItem{
			ID:       l.ID,
			Status:   l.Status,
			DeviceID: l.DeviceID,
			Payload:  l.Payload,
			Cursor:   l.Cursor,
		}
	}
	writeJSON(w, http.StatusOK, changeLookupResponse{Results: items, Count: len(items)})
}

// malformedChangeQueryPath reports whether p targets the change-log batch
// lookup but is not at its exact location
// (/v1/documents/{documentID}/changes/query): a missing "changes" segment, an
// extra segment, a trailing slash (an empty trailing segment), or a "query"
// segment in a position short of the registered shape. ServeMux would answer
// those with a redirect or a plain-text 404/405; every failure of this
// endpoint must be a JSON 400 instead and never a redirect. Empty segments
// are already rejected by the guard itself.
//
// "query" is treated as the endpoint keyword only in its terminal segment
// position (the third segment, index 2); a document identifier literally
// named "query" occupies an identifier position (index 0) and keeps its
// ordinary routes.
func malformedChangeQueryPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guards; "query" there is an ordinary identifier.
	if len(segs) >= 2 && segs[1] == "crdt" {
		return false
	}
	// The named-snapshot-version subtree owns its own shape verdict.
	if len(segs) >= 3 && segs[0] != "" && segs[1] == "snapshots" && segs[2] == "versions" {
		return false
	}
	for i, seg := range segs {
		if seg != "query" {
			continue
		}
		// Identifier position: a document named "query" is an ordinary id.
		if i == 0 {
			continue
		}
		// Endpoint keyword position: the third segment must be exactly
		// "query" with a non-empty documentID and "changes" around it, and no
		// segment may follow. Any other occurrence is a malformed path.
		if i == 2 && len(segs) == 3 &&
			segs[0] != "" &&
			segs[1] == "changes" {
			return false
		}
		return true
	}
	return false
}

// Package crdt is the CRDT state service: an automatically mergeable state
// layer that sits beside the change event log and never touches it.
//
// A document's CRDT type is declared with its first operation batch —
// "counter", "gset", "register" or "orset" — and never changes afterward; two
// batches declaring different types concurrently serialize in one transaction
// on the shared connection and exactly one takes effect.
//
// A counter carries each device's accumulated contribution; contributions
// only move forward and the merge is the sum of per-device maxima. A gset
// adds strings; the merge is the sorted union. A register carries an arbitrary
// JSON value and a strictly increasing per-device version; the merge is the
// greatest version, ties broken by the smaller operation id. An orset tags
// each add with its operation id and a remove tombstones only the adds it has
// observed, so concurrent removes never delete later adds; the merge is the
// sorted set of elements with a live tag. Every merge is commutative,
// associative and idempotent, so any reader converges to the same value.
//
// Operation ids are stable and unique per document; a repeat with the same
// device and comparison content is idempotent, any other repeat a conflict.
// Compaction trims rows that no longer participate in a merge while keeping
// one fixed-size identity digest per trimmed id, so idempotency and conflict
// decisions are unchanged afterward.
//
// The service owns only its own tables. Registration and authorization are
// reached through its Gate interface inside the write transaction, and
// committed state changes are published to in-memory state subscriptions. It
// never writes change rows, allocates cursors or reads another service's
// storage.
package crdt

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
)

// CRDT document types.
const (
	// TypeCounter is the grow-only counter: the merged value is the sum of
	// each device's maximum accumulated contribution.
	TypeCounter = "counter"
	// TypeGSet is the grow-only set: the merged value is the union of all
	// added elements.
	TypeGSet = "gset"
	// TypeRegister is the last-writer-wins register: the merged value is the
	// value of the operation with the greatest version, ties broken by the
	// lexicographically smaller operation id.
	TypeRegister = "register"
	// TypeORSet is the observed-remove set: the merged value is the set of
	// elements with at least one add not tombstoned by an observed remove.
	TypeORSet = "orset"
)

// OR-Set operation actions.
const (
	// ORSetAdd adds the operation's element with a fresh tag.
	ORSetAdd = "add"
	// ORSetRemove tombstones every add tag for the element that the operation
	// observes.
	ORSetRemove = "remove"
)

// ErrNotFound reports that no CRDT operation has ever been committed for the
// document, so it has neither a type nor a merged state yet. The caller maps
// it to 404.
var ErrNotFound = errors.New("crdt state not found")

// ErrConflict reports a rejected CRDT batch: the document's type is already
// fixed to another type, a counter contribution regressed, or an operation id
// already exists with different content or origin. Nothing is written; the
// caller maps it to 409.
type ErrConflict struct {
	// ID is the conflicting operation id when one is known; it is empty for a
	// document-level conflict (a mismatched declared type).
	ID string
	// Reason carries a short, machine-facing description of the conflict.
	Reason string
}

func (e *ErrConflict) Error() string {
	if e.ID != "" {
		return fmt.Sprintf("crdt conflict for operation %q: %s", e.ID, e.Reason)
	}
	return "crdt conflict: " + e.Reason
}

// Op is one element of an inbound CRDT batch.
//
// For a counter, Value is the device's accumulated contribution: it must be a
// JSON number that is a non-negative integer, and it may never decrease for
// the same device. Elements and Version are unused.
//
// For a gset, Elements lists the strings the operation adds to the set and
// must be non-empty; Value and Version are unused.
//
// For a register, Value is an arbitrary JSON value stored verbatim and
// Version is a non-negative integer that must be strictly greater than every
// version the same device has already had accepted. Elements is unused.
//
// For an orset, Action is "add" or "remove" and Element is the non-empty
// string the operation adds or removes. Value, Elements and Version are
// unused.
type Op struct {
	ID       string          // client-supplied stable id, unique per document
	DeviceID string          // originating device (shared by the whole batch)
	Value    json.RawMessage // counter: accumulated contribution; register: the value
	Elements []string        // gset: elements to add
	Version  int64           // register: logical version, per-device strictly increasing
	Action   string          // orset: ORSetAdd or ORSetRemove
	Element  string          // orset: the element the action applies to
}

// State is a document's merged CRDT state.
//
// Value holds the type-specific merged result: for a counter it decodes to the
// JSON integer sum of per-device maxima; for a gset it decodes to the sorted
// JSON array of every accepted element (an empty set is []); for a register it
// is the winning operation's JSON value, exactly as submitted; for an orset it
// decodes to the sorted JSON array of the elements with at least one live add
// (an empty set is []).
type State struct {
	Type  string          `json:"type"`
	Value json.RawMessage `json:"value"`
}

// Result reports the outcome for one element of an accepted CRDT batch.
type Result struct {
	ID      string `json:"id"`
	Created bool   `json:"created"`
}

// Snapshot is a document's merged CRDT state together with the storage
// footprint of that state: Operations counts the stored operations the merge
// is derived from (counter and gset: rows of the operation log; register: the
// retained per-device operations; orset: the add tags, live or tombstoned)
// and Tombstones counts the stored orset tombstones (always zero for the
// other types). Both counts are non-negative; compaction drives them down to
// the operations and tombstones that still participate in the merge.
type Snapshot struct {
	Type       string          // the document's fixed CRDT type
	Value      json.RawMessage // the merged value, exactly as GetState derives it
	Operations int64           // stored operations the merge is derived from
	Tombstones int64           // stored orset tombstones; 0 for counter, gset and register
}

// Gate is the only seam the CRDT service uses to reach the registration and
// permission layers. It is evaluated inside the write transaction, so a
// rejected submission is judged before any CRDT content is observed.
type Gate interface {
	// DeviceAuthorizedTx returns nil when the device is registered and
	// authorized, store.ErrDeviceNotFound for an unregistered device and
	// store.ErrPermissionDenied after a revoke.
	DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error
}

// schema is created when the service is constructed. Table shapes are
// unchanged from the pre-refactor layout, so CRDT data already on disk stays
// readable after the split.
const schema = `
CREATE TABLE IF NOT EXISTS crdt_documents (
	document_id TEXT NOT NULL PRIMARY KEY,
	type        TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS crdt_ops (
	document_id TEXT NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	value       BLOB,
	PRIMARY KEY (document_id, id)
);
CREATE TABLE IF NOT EXISTS crdt_counter_values (
	document_id TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	value       INTEGER NOT NULL,
	PRIMARY KEY (document_id, device_id)
);
CREATE TABLE IF NOT EXISTS crdt_set_elements (
	document_id TEXT NOT NULL,
	element     TEXT NOT NULL,
	PRIMARY KEY (document_id, element)
);
CREATE TABLE IF NOT EXISTS crdt_register_ops (
	document_id TEXT NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	version     INTEGER NOT NULL,
	value       BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
CREATE TABLE IF NOT EXISTS crdt_orset_tags (
	document_id TEXT NOT NULL,
	element     TEXT NOT NULL,
	op_id       TEXT NOT NULL,
	PRIMARY KEY (document_id, element, op_id)
);
CREATE TABLE IF NOT EXISTS crdt_orset_tombstones (
	document_id TEXT NOT NULL,
	element     TEXT NOT NULL,
	op_id       TEXT NOT NULL,
	removed_by  TEXT NOT NULL,
	PRIMARY KEY (document_id, element, op_id)
);
-- op_identities keeps, for each operation id whose merge row compaction
-- trimmed away, the only information idempotency and conflict decisions still
-- need: the originating device and a digest of the type-specific comparison
-- content. Compaction never trims this table; it does not participate in any
-- merge and holds a fixed-size digest rather than the operation payload.
CREATE TABLE IF NOT EXISTS crdt_op_identities (
	document_id TEXT NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	digest      BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
`

content.content:
1	package crdt
2	
3	import (
4		"database/sql"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"sync"
9	
10		"github.com/alicegogogogogo/local-first-sync-service/internal/store"
11	)
12	
13	// Service is the CRDT state service: the durable CRDT tables plus the
14	// in-memory merged-state subscriptions, serialized against each other.
15	type Service struct {
16		db   *sql.DB
17		gate Gate
18	
19		// mu serializes submissions and compactions against each other and against
20		// a subscription's atomic register-plus-initial-read. Holding it across a
21		// state-changing commit and its notification makes notifications leave in
22		// transaction-commit order, and makes a commit's state land either in a
23		// subscriber's initial read or in its queue, never both and never neither.
24		// The single database connection already serializes the transactions
25		// themselves, so this costs no concurrency.
26		mu sync.Mutex
27	
28		subMu     sync.Mutex
29		subs      map[crdtSubKey]map[uint64]*Subscription
30		nextSubID uint64
31		subWG     sync.WaitGroup
32		closed    bool
33	}
34	
35	// New constructs the CRDT state service over the shared kernel handle and
36	// creates its tables. gate answers the registration/permission checks inside
37	// a write transaction; it may be nil for callers that only read state.
38	func New(kernel *store.Store, gate Gate) (*Service, error) {
39		db := kernel.DB()
40		if _, err := db.Exec(schema); err != nil {
41			return nil, err
42		}
43		return &Service{
44			db:   db,
45			gate: gate,
46			subs: make(map[crdtSubKey]map[uint64]*Subscription),
47		}, nil
48	}
49	
50	// SubmitOps validates and commits one CRDT batch atomically.
51	//
52	// declaredType fixes the type on the document's first batch; every later
53	// batch must declare the same type. Two batches declaring different types
54	// race in one serialized transaction, so exactly one wins and the other gets
55	// an *ErrConflict (409).
56	//
57	// The device is gated first (store.ErrDeviceNotFound /
58	// store.ErrPermissionDenied) before any CRDT content is read. Every operation
59	// is then resolved against the committed history: a repeated id is idempotent
60	// only with the same device and content, otherwise it is an *ErrConflict; a
61	// counter contribution below the device's current maximum, or a register
62	// version not strictly greater than the device's accepted versions, is
63	// likewise an *ErrConflict. Any failure rejects the whole batch. Results come
64	// back in request order.
65	//
66	// When the committed batch actually moved the merged state the document's
67	// state subscribers are notified with the new merged state after the commit;
68	// idempotent repeats, rejected batches and no-op additions or removals change
69	// nothing and notify nobody.
70	func (s *Service) SubmitOps(documentID, declaredType string, ops []Op) ([]Result, error) {
71		s.mu.Lock()
72		defer s.mu.Unlock()
73	
74		tx, err := s.db.Begin()
75		if err != nil {
76			return nil, err
77		}
78		defer func() { _ = tx.Rollback() }()
79	
80		deviceID := ops[0].DeviceID
81	
82		// Registration and permission are enforced before any CRDT content is
83		// observed, so a rejected submission cannot reveal type or state.
84		if s.gate != nil {
85			if err := s.gate.DeviceAuthorizedTx(tx, documentID, deviceID); err != nil {
86				return nil, err
87			}
88		}
89	
90		// Resolve the document type: fixed on the first accepted batch.
91		var docType string
92		err = tx.QueryRow(
93			`SELECT type FROM crdt_documents WHERE document_id = ?`, documentID,
94		).Scan(&docType)
95		switch {
96		case errors.Is(err, sql.ErrNoRows):
97			// First batch for this document: its declared type wins the race.
98			if _, err := tx.Exec(
99				`INSERT INTO crdt_documents (document_id, type) VALUES (?, ?)`,
100				documentID, declaredType,
101			); err != nil {
102				return nil, err
103			}
104			docType = declaredType
105		case err != nil:
106			return nil, err
107		default:
108			if docType != declaredType {
109				return nil, &ErrConflict{
110					Reason: fmt.Sprintf("document type is already %q", docType),
111				}
112			}
113		}
114	
115		results := make([]Result, len(ops))
116	
117		var stateChanged bool
118		switch docType {
119		case TypeCounter:
120			changed, err := applyCounterOps(tx, documentID, ops, results)
121			if err != nil {
122				return nil, err
123			}
124			stateChanged = changed
125		case TypeGSet:
126			changed, err := applyGSetOps(tx, documentID, ops, results)
127			if err != nil {
128				return nil, err
129			}
130			stateChanged = changed
131		case TypeRegister:
132			changed, err := applyRegisterOps(tx, documentID, ops, results)
133			if err != nil {
134				return nil, err
135			}
136			stateChanged = changed
137		case TypeORSet:
138			changed, err := applyORSetOps(tx, documentID, ops, results)
139			if err != nil {
140				return nil, err
141			}
142			stateChanged = changed
143		}
144	
145		if err := tx.Commit(); err != nil {
146			return nil, err
147		}
148		if stateChanged {
149			// The committed batch moved the merged state; re-derive it (the merge
150			// is never cached) and publish it after commit, so a subscriber only
151			// ever observes a durable state and commits arrive in commit order.
152			state, err := s.GetState(documentID)
153			if err != nil {
154				return results, nil
155			}
156			s.notifySubscribers(documentID, state)
157		}
158		return results, nil
159	}
160	
161	// applyCounterOps resolves and applies every counter operation inside tx. A
162	// repeated id is idempotent only with the same device and contribution. A new
163	// id with a contribution below the device's stored maximum regresses the
164	// counter and is rejected; an equal contribution is an accepted no-op; a
165	// larger one advances the device's maximum. It reports whether the merged
166	// state actually changed — only an advancing contribution moves the sum.
167	func applyCounterOps(tx *sql.Tx, documentID string, ops []Op, results []Result) (bool, error) {
168		changed := false
169		for i, op := range ops {
170			value, err := decodeCounterValue(op.Value)
171			if err != nil {
172				return false, &ErrConflict{ID: op.ID, Reason: err.Error()}
173			}
174	
175			var existingDevice string
176			var existingValue []byte
177			err = tx.QueryRow(
178				`SELECT device_id, value FROM crdt_ops WHERE document_id = ? AND id = ?`,
179				documentID, op.ID,
180			).Scan(&existingDevice, &existingValue)
181			switch {
182			case errors.Is(err, sql.ErrNoRows):
183				// The merge row may have been trimmed by compaction; the retained
184				// identity still decides between idempotent replay and conflict.
185				idempotent, idErr := resolveTrimmedIdentity(
186					tx, documentID, TypeCounter,
187					"operation id already exists with a different device or value", op,
188				)
189				if idErr != nil {
190					return false, idErr
191				}
192				if idempotent {
193					results[i] = Result{ID: op.ID, Created: false}
194					continue
195				}
196				// New id: enforce monotonicity against this device's maximum.
197				var current sql.NullInt64
198				if scanErr := tx.QueryRow(
199					`SELECT value FROM crdt_counter_values WHERE document_id = ? AND device_id = ?`,
200					documentID, op.DeviceID,
201				).Scan(&current); scanErr != nil && !errors.Is(scanErr, sql.ErrNoRows) {
202					return false, scanErr
203				}
204				if current.Valid && value < current.Int64 {
205					return false, &ErrConflict{
206						ID:     op.ID,
207						Reason: "counter contribution must not decrease",
208					}
209				}
210				if _, err := tx.Exec(
211					`INSERT INTO crdt_ops (document_id, id, device_id, value) VALUES (?, ?, ?, ?)`,
212					documentID, op.ID, op.DeviceID, []byte(op.Value),
213				); err != nil {
214					return false, err
215				}
216				if !current.Valid || value > current.Int64 {
217					if _, err := tx.Exec(
218						`INSERT INTO crdt_counter_values (document_id, device_id, value) VALUES (?, ?, ?)
219						 ON CONFLICT (document_id, device_id) DO UPDATE SET value = excluded.value`,
220						documentID, op.DeviceID, value,
221					); err != nil {
222						return false, err
223					}
224					changed = true
225				}
226				results[i] = Result{ID: op.ID, Created: true}
227			case err != nil:
228				return false, err
229			default:
230				if existingDevice != op.DeviceID || !store.JSONEqual(existingValue, op.Value) {
231					return false, &ErrConflict{
232						ID:     op.ID,
233						Reason: "operation id already exists with a different device or value",
234					}
235				}
236				results[i] = Result{ID: op.ID, Created: false}
237			}
238		}
239		return changed, nil
240	}
241	
242	// applyGSetOps resolves and applies every grow-only-set operation inside tx.
243	// A repeated id is idempotent only with the same device and the same set of
244	// elements (element order is irrelevant to the merge). New elements are
245	// inserted into the union table; re-adding an element changes nothing. It
246	// reports whether the merged state actually changed.
247	func applyGSetOps(tx *sql.Tx, documentID string, ops []Op, results []Result) (bool, error) {
248		changed := false
249		for i, op := range ops {
250			var existingDevice string
251			var existingElements []byte
252			err := tx.QueryRow(
253				`SELECT device_id, value FROM crdt_ops WHERE document_id = ? AND id = ?`,
254				documentID, op.ID,
255			).Scan(&existingDevice, &existingElements)
256			switch {
257			case errors.Is(err, sql.ErrNoRows):
258				idempotent, idErr := resolveTrimmedIdentity(
259					tx, documentID, TypeGSet,
260					"operation id already exists with a different device or elements", op,
261				)
262				if idErr != nil {
263					return false, idErr
264				}
265				if idempotent {
266					results[i] = Result{ID: op.ID, Created: false}
267					continue
268				}
269				// New id; insert the op and its elements below.
270			case err != nil:
271				return false, err
272			default:
273				if existingDevice != op.DeviceID || !stringSetEqual(existingElements, op.Elements) {
274					return false, &ErrConflict{
275						ID:     op.ID,
276						Reason: "operation id already exists with a different device or elements",
277					}
278				}
279				results[i] = Result{ID: op.ID, Created: false}
280				continue
281			}
282	
283			if _, err := tx.Exec(
284				`INSERT INTO crdt_ops (document_id, id, device_id, value) VALUES (?, ?, ?, ?)`,
285				documentID, op.ID, op.DeviceID, []byte(encodeSetElements(op.Elements)),
286			); err != nil {
287				return false, err
288			}
289			for _, element := range op.Elements {
290				// The union table is an identity insert: a repeated element simply
291				// exists once, and only a genuinely new element moves the merge.
292				res, err := tx.Exec(
293					`INSERT OR IGNORE INTO crdt_set_elements (document_id, element) VALUES (?, ?)`,
294					documentID, element,
295				)
296				if err != nil {
297					return false, err
298				}
299				if n, err := res.RowsAffected(); err == nil && n > 0 {
300					changed = true
301				}
302			}
303			results[i] = Result{ID: op.ID, Created: true}
304		}
305		return changed, nil
306	}
307	
308	// applyRegisterOps resolves and applies every register operation inside tx. A
309	// repeated id is idempotent only with the same device, version and value. A
310	// new id whose version is not strictly greater than every version already
311	// accepted from the same device regresses (or stalls) the device's clock and
312	// is rejected. It reports whether the merged state actually changed.
313	func applyRegisterOps(tx *sql.Tx, documentID string, ops []Op, results []Result) (bool, error) {
314		// The merged value before the batch, so a batch that leaves the winner's
315		// value untouched reports no change and notifies nobody.
316		prev, prevOK, err := registerWinner(tx, documentID)
317		if err != nil {
318			return false, err
319		}
320	
321		for i, op := range ops {
322			if op.Version < 0 {
323				// The API boundary rejects negative versions; a negative version
324				// here means the caller skipped validation.
325				return false, &ErrConflict{ID: op.ID, Reason: "register version must be a non-negative integer"}
326			}
327	
328			var existingDevice string
329			var existingVersion int64
330			var existingValue []byte
331			err := tx.QueryRow(
332				`SELECT device_id, version, value FROM crdt_register_ops WHERE document_id = ? AND id = ?`,
333				documentID, op.ID,
334			).Scan(&existingDevice, &existingVersion, &existingValue)
335			switch {
336			case errors.Is(err, sql.ErrNoRows):
337				// An older per-device version may have been trimmed; the retained
338				// identity still decides replay versus conflict before the version
339				// monotonicity gate, which only applies to an id never accepted.
340				idempotent, idErr := resolveTrimmedIdentity(
341					tx, documentID, TypeRegister,
342					"operation id already exists with a different device, version or value", op,
343				)
344				if idErr != nil {
345					return false, idErr
346				}
347				if idempotent {
348					results[i] = Result{ID: op.ID, Created: false}
349					continue
350				}
351				// New id: the device's versions only move strictly forward. The
352				// per-device maximum is derived from the retained operations, so
353				// the decision survives compaction and restarts.
354				var maxVersion sql.NullInt64
355				if scanErr := tx.QueryRow(
356					`SELECT MAX(version) FROM crdt_register_ops WHERE document_id = ? AND device_id = ?`,
357					documentID, op.DeviceID,
358				).Scan(&maxVersion); scanErr != nil {
359					return false, scanErr
360				}
361				if maxVersion.Valid && op.Version <= maxVersion.Int64 {
362					return false, &ErrConflict{
363						ID:     op.ID,
364						Reason: "register version must be greater than the device's previously accepted version",
365					}
366				}
367				if _, err := tx.Exec(
368					`INSERT INTO crdt_register_ops (document_id, id, device_id, version, value) VALUES (?, ?, ?, ?, ?)`,
369					documentID, op.ID, op.DeviceID, op.Version, []byte(op.Value),
370				); err != nil {
371					return false, err
372				}
373				results[i] = Result{ID: op.ID, Created: true}
374			case err != nil:
375				return false, err
376			default:
377				if existingDevice != op.DeviceID || existingVersion != op.Version || !store.JSONEqual(existingValue, op.Value) {
378					return false, &ErrConflict{
379						ID:     op.ID,
380						Reason: "operation id already exists with a different device, version or value",
381					}
382				}
383				results[i] = Result{ID: op.ID, Created: false}
384			}
385		}
386	
387		next, nextOK, err := registerWinner(tx, documentID)
388		if err != nil {
389			return false, err
390		}
391		// The merge is the winner's value; a new winner carrying a JSON-equal
392		// value does not move the state.
393		changed := prevOK != nextOK || (prevOK && nextOK && !store.JSONEqual(prev, next))
394		return changed, nil
395	}
396	
397	// registerWinner returns the value the register currently merges to: the
398	// value of the accepted operation with the greatest version, ties broken by
399	// the lexicographically smaller operation id. It reports false when the
400	// document has no accepted register operation yet.
401	func registerWinner(tx *sql.Tx, documentID string) (json.RawMessage, bool, error) {
402		var value []byte
403		err := tx.QueryRow(
404			`SELECT value FROM crdt_register_ops WHERE document_id = ?
405			 ORDER BY version DESC, id ASC LIMIT 1`,
406			documentID,
407		).Scan(&value)
408		switch {
409		case errors.Is(err, sql.ErrNoRows):
410			return nil, false, nil
411		case err != nil:
412			return nil, false, err
413		default:
414			return json.RawMessage(value), true, nil
415		}
416	}
417	
418	// applyORSetOps resolves and applies every observed-remove-set operation
419	// inside tx. A repeated id is idempotent only with the same device, action and
420	// element; an idempotent replay applies nothing, so a replayed remove never
421	// tombstones adds that landed after its first acceptance. An add tags the
422	// element with its own operation id; a remove tombstones exactly the tags
423	// already accepted for the element. Removing an element with no live tags is
424	// an accepted no-op. It reports whether the merged state actually changed.
425	func applyORSetOps(tx *sql.Tx, documentID string, ops []Op, results []Result) (bool, error) {
426		prev, err := queryORSetElements(tx, documentID)
427		if err != nil {
428			return false, err
429		}
430	
431		for i, op := range ops {
432			if op.Action != ORSetAdd && op.Action != ORSetRemove {
433				return false, &ErrConflict{ID: op.ID, Reason: `orset action must be "add" or "remove"`}
434			}
435	
436			var existingDevice string
437			var existingContent []byte
438			err := tx.QueryRow(
439				`SELECT device_id, value FROM crdt_ops WHERE document_id = ? AND id = ?`,
440				documentID, op.ID,
441			).Scan(&existingDevice, &existingContent)
442			switch {
443			case errors.Is(err, sql.ErrNoRows):
444				// New id; insert the op and apply its effect below.
445			case err != nil:
446				return false, err
447			default:
448				if existingDevice != op.DeviceID || !store.JSONEqual(existingContent, encodeORSetContent(op.Action, op.Element)) {
449					return false, &ErrConflict{
450						ID:     op.ID,
451						Reason: "operation id already exists with a different device, action or element",
452					}
453				}
454				results[i] = Result{ID: op.ID, Created: false}
455				continue
456			}
457	
458			if _, err := tx.Exec(
459				`INSERT INTO crdt_ops (document_id, id, device_id, value) VALUES (?, ?, ?, ?)`,
460				documentID, op.ID, op.DeviceID, []byte(encodeORSetContent(op.Action, op.Element)),
461			); err != nil {
462				return false, err
463			}
464			if op.Action == ORSetAdd {
465				if _, err := tx.Exec(
466					`INSERT OR IGNORE INTO crdt_orset_tags (document_id, element, op_id) VALUES (?, ?, ?)`,
467					documentID, op.Element, op.ID,
468				); err != nil {
469					return false, err
470				}
471			} else {
472				// Tombstone exactly the tags this remove observes: the adds
473				// accepted before it. Tags created later are not in the table yet
474				// and survive; already-tombstoned tags are an identity insert.
475				if _, err := tx.Exec(
476					`INSERT OR IGNORE INTO crdt_orset_tombstones (document_id, element, op_id, removed_by)
477					 SELECT ?, ?, op_id, ? FROM crdt_orset_tags
478					 WHERE document_id = ? AND element = ?`,
479					documentID, op.Element, op.ID, documentID, op.Element,
480				); err != nil {
481					return false, err
482				}
483			}
484			results[i] = Result{ID: op.ID, Created: true}
485		}
486	
487		next, err := queryORSetElements(tx, documentID)
488		if err != nil {
489			return false, err
490		}
491		return !stringSliceEqual(prev, next), nil
492	}
493	
494	// orsetLiveElementsSQL selects the elements with at least one add tag no
495	// tombstone covers, in ascending order — the orset merge, derived from the
496	// accepted operations rather than cached.
497	const orsetLiveElementsSQL = `
498	SELECT DISTINCT element FROM crdt_orset_tags t
499	WHERE t.document_id = ? AND NOT EXISTS (
500		SELECT 1 FROM crdt_orset_tombstones x
501		WHERE x.document_id = t.document_id
502		  AND x.element = t.element
503		  AND x.op_id = t.op_id
504	)
505	ORDER BY element ASC`
506	
507	// orsetQuerier is satisfied by both *sql.Tx (inside a submission) and *sql.DB
508	// (a state read), so the merge query exists exactly once.
509	type orsetQuerier interface {
510		Query(query string, args ...any) (*sql.Rows, error)
511	}
512	
513	// queryORSetElements returns the document's live orset elements in ascending
514	// order. The empty set is an empty slice, never nil, so it marshals as [].
515	func queryORSetElements(q orsetQuerier, documentID string) ([]string, error) {
516		rows, err := q.Query(orsetLiveElementsSQL, documentID)
517		if err != nil {
518			return nil, err
519		}
520		elements := make([]string, 0)
521		for rows.Next() {
522			var element string
523			if err := rows.Scan(&element); err != nil {
524				_ = rows.Close()
525				return nil, err
526			}
527			elements = append(elements, element)
528		}
529		if err := rows.Err(); err != nil {
530			_ = rows.Close()
531			return nil, err
532		}
533		_ = rows.Close()
534		return elements, nil
535	}
536	
537	// encodeORSetContent renders an orset operation's content (its action and
538	// element) as a JSON object for durable storage.
539	func encodeORSetContent(action, element string) json.RawMessage {
540		raw, err := json.Marshal(struct {
541			Action  string `json:"action"`
542			Element string `json:"element"`
543		}{Action: action, Element: element})
544		if err != nil {
545			// Strings always marshal.
546			return json.RawMessage(`{"action":"","element":""}`)
547		}
548		return raw
549	}
550	
551	// stringSliceEqual reports whether a and b hold the same strings in the same
552	// order. Both orset element lists are ascending, so it is set equality.
553	func stringSliceEqual(a, b []string) bool {
554		if len(a) != len(b) {
555			return false
556		}
557		for i := range a {
558			if a[i] != b[i] {
559				return false
560			}
561		}
562		return true
563	}
564	
565	// decodeCounterValue requires raw to be a non-negative JSON integer with no
566	// fraction or exponent. Floats, strings, booleans and null are rejected at the
567	// API boundary; a malformed integer here means the caller skipped validation.
568	func decodeCounterValue(raw json.RawMessage) (int64, error) {
569		var n int64
570		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
571			return 0, errors.New("counter value must be a non-negative integer")
572		}
573		return n, nil
574	}
575	
576	// encodeSetElements renders the elements of one gset operation as a JSON array
577	// for durable storage of the original operation content.
578	func encodeSetElements(elements []string) json.RawMessage {
579		raw, err := json.Marshal(elements)
580		if err != nil {
581			return json.RawMessage("[]")
582		}
583		return raw
584	}
585	
586	// stringSetEqual reports whether raw (a JSON array of strings stored for a
587	// prior gset operation) contains exactly the elements of want, ignoring
588	// duplicates and order: the content of a set operation is the set of elements.
589	func stringSetEqual(raw json.RawMessage, want []string) bool {
590		var got []string
591		if err := json.Unmarshal(raw, &got); err != nil {
592			return false
593		}
594		set := make(map[string]struct{}, len(got))
595		for _, e := range got {
596			set[e] = struct{}{}
597		}
598		for _, e := range want {
599			if _, ok := set[e]; !ok {
600				return false
601			}
602			delete(set, e)
603		}
604		return len(set) == 0
605	}
606	
607	// GetState returns the merged CRDT state for documentID. A document with no
608	// committed operations yields ErrNotFound (the caller answers 404).
609	//
610	// The merged value is derived from the per-device maxima (counter), the union
611	// table (gset), the version/id ordering of accepted operations (register) or
612	// the live tags minus tombstones (orset), not cached.
613	func (s *Service) GetState(documentID string) (State, error) {
614		var docType string
615		err := s.db.QueryRow(
616			`SELECT type FROM crdt_documents WHERE document_id = ?`, documentID,
617		).Scan(&docType)
618		switch {
619		case errors.Is(err, sql.ErrNoRows):
620			return State{}, ErrNotFound
621		case err != nil:
622			return State{}, err
623		}
624	
625		switch docType {
626		case TypeCounter:
627			var total int64
628			if err := s.db.QueryRow(
629				`SELECT COALESCE(SUM(value), 0) FROM crdt_counter_values WHERE document_id = ?`,
630				documentID,
631			).Scan(&total); err != nil {
632				return State{}, err
633			}
634			raw, err := json.Marshal(total)
635			if err != nil {
636				return State{}, err
637			}
638			return State{Type: docType, Value: raw}, nil
639		case TypeGSet:
640			rows, err := s.db.Query(
641				`SELECT element FROM crdt_set_elements WHERE document_id = ? ORDER BY element ASC`,
642				documentID,
643			)
644			if err != nil {
645				return State{}, err
646			}
647			elements := make([]string, 0)
648			for rows.Next() {
649				var element string
650				if err := rows.Scan(&element); err != nil {
651					_ = rows.Close()
652					return State{}, err
653				}
654				elements = append(elements, element)
655			}
656			if err := rows.Err(); err != nil {
657				_ = rows.Close()
658				return State{}, err
659			}
660			_ = rows.Close()
661			raw, err := json.Marshal(elements)
662			if err != nil {
663				return State{}, err
664			}
665			return State{Type: docType, Value: raw}, nil
666		case TypeRegister:
667			// A document's type row commits together with its first batch, so a
668			// register document always has at least one accepted operation.
669			var value []byte
670			if err := s.db.QueryRow(
671				`SELECT value FROM crdt_register_ops WHERE document_id = ?
672				 ORDER BY version DESC, id ASC LIMIT 1`,
673				documentID,
674			).Scan(&value); err != nil {
675				return State{}, err
676			}
677			return State{Type: docType, Value: json.RawMessage(value)}, nil
678		case TypeORSet:
679			elements, err := queryORSetElements(s.db, documentID)
680			if err != nil {
681				return State{}, err
682			}
683			raw, err := json.Marshal(elements)
684			if err != nil {
685				return State{}, err
686			}
687			return State{Type: docType, Value: raw}, nil
688		default:
689			return State{}, fmt.Errorf("unknown crdt type %q stored for document", docType)
690		}
691	}
692

