// DeregisterDevice removes a registered device together with every record it
// owns — its sessions, the attachments it created (chunks, sealed state and
// unfinished uploads included), the access grants it held, and its
// document-permission rows — all in one serialized transaction that commits
// synchronously. An unknown or already deregistered device yields
// store.ErrDeviceNotFound and writes nothing, so a repeat deregistration
// misses exactly the way a never-registered id does and concurrent calls take
// effect at most once. Shared digest-addressed content is reclaimed only when
// the last completed attachment referencing it is gone; other devices'
// changes, snapshots and document content are untouched.
//
// After the commit the same id may register again as a brand-new device — no
// session, permission or attachment is inherited — and every live
// subscription the device held across both push channels is ended
// immediately, stickily.
func (a *App) DeregisterDevice(deviceID string) error {
	tx, err := a.Store.DB().Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	if err := store.DeleteDeviceTx(tx, deviceID); err != nil {
		return err
	}
	if err := a.Authz.DeleteDevicePermissionsTx(tx, deviceID); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return err
	}

	// End the device's live subscriptions only after the cascade is durable:
	// a reconnect attempt after the close finds the backing session gone
	// (404), so the connection cannot immediately re-establish itself.
	a.events.SignalDeviceDeregistered(deviceID)
	a.crdt.SignalDeviceDeregistered(deviceID)
	return nil
}

// ---- Document-level deletion. ----

// DeleteDocument removes a registered device's whole document in one
// serialized, synchronously committed transaction. The calling device is
// declared by deviceId — no new authentication is introduced.
//
// The fixed verdict order is taken inside the transaction, before any cleanup:
//
//   - an unregistered device yields store.ErrDeviceNotFound (404) and writes
//     nothing;
//   - a device whose permission for the document was revoked yields
//     store.ErrPermissionDenied (403) and no cleanup runs;
//   - a document with no durable data anywhere — never created or already
//     deleted — yields events.ErrDocumentNotFound (404) and writes nothing.
//
// On success every row of the document is removed as one judgment: its online
// and trimmed change log, the retained idempotency summaries, its snapshots
// and named snapshot-version markers, its CRDT state and the per-document
// permission ledger. The same id is a brand-new document afterward — the
// cursor space restarts at 1 — and inherits no history or version names.
// Concurrent deletes commit at most once because the existence verdict and
// the deletions share one immediate transaction on the single connection.
//
// Only after the commit is durable are the document's live subscriptions
// ended (close code 4420 on both push channels) and dropped from the
// management registry; other documents' and devices' connections are
// untouched.
func (a *App) DeleteDocument(documentID, deviceID string) error {
	tx, err := a.Store.DB().Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	// Registration first, then permission, both before any document content
	// is observed: a rejected delete reveals nothing and cleans nothing.
	if err := a.Authz.AuthorizedTx(tx, documentID, deviceID); err != nil {
		return err
	}

	eventsExist, err := a.events.DocumentDataExistsTx(tx, documentID)
	if err != nil {
		return err
	}
	crdtExist, err := a.crdt.DocumentDataExistsTx(tx, documentID)
	if err != nil {
		return err
	}
	// A ledger-only deviation row also counts as document data, so a document
	// whose only durable trace is a grant/revoke still deletes cleanly and the
	// re-created id inherits no authorization state.
	ledgerExist, err := a.Authz.DocumentHasRowsTx(tx, documentID)
	if err != nil {
		return err
	}
	if !eventsExist && !crdtExist && !ledgerExist {
		return events.ErrDocumentNotFound
	}

	if err := a.events.DeleteDocumentDataTx(tx, documentID); err != nil {
		return err
	}
	if err := a.crdt.DeleteDocumentDataTx(tx, documentID); err != nil {
		return err
	}
	if err := a.Authz.DeleteDocumentPermissionsTx(tx, documentID); err != nil {
		return err
	}

	if err := tx.Commit(); err != nil {
		return err
	}

	// End the document's live subscriptions on both channels and drop them
	// from the management registry only after the cleanup is durable: the
	// close is one-shot per connection, so a client re-subscribing to the
	// now-fresh id opens a new connection and never reopens the ended ones.
	a.events.SignalDocumentDeleted(documentID)
	a.crdt.SignalDocumentDeleted(documentID)
	a.CloseDocumentPush(documentID)
	return nil
}

// ---- Permission service boundary. ----

// SetDocumentPermission delegates to the permission service.
func (a *App) SetDocumentPermission(documentID, deviceID string, authorized bool) (bool, error) {
	return a.Authz.SetDocumentPermission(documentID, deviceID, authorized)
}

// DocumentAuthorized delegates to the permission service.
func (a *App) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	return a.Authz.DocumentAuthorized(documentID, deviceID)
}

// ListDocumentPermissions delegates to the permission service.
func (a *App) ListDocumentPermissions(documentID string, limit, offset int64) ([]authz.PermissionEntry, error) {
	return a.Authz.ListDocumentPermissions(documentID, limit, offset)
}

// ---- CRDT state service boundary. ----

// SubmitCRDTOps delegates to the CRDT state service.
func (a *App) SubmitCRDTOps(documentID, declaredType string, ops []crdt.Op) ([]crdt.Result, error) {
	return a.crdt.SubmitOps(documentID, declaredType, ops)
}

// GetCRDTState delegates to the CRDT state service.
func (a *App) GetCRDTState(documentID string) (crdt.State, error) {
	return a.crdt.GetState(documentID)
}

// CompactCRDT delegates to the CRDT state service.
func (a *App) CompactCRDT(documentID, deviceID string) (crdt.Snapshot, error) {
	return a.crdt.Compact(documentID, deviceID)
}

// CompactSessionCRDT compacts a document's CRDT state for a caller whose
// device identity was resolved from a session by the HTTP layer, delegating
// to the CRDT state service's gated compaction: the registration/permission
// verdict is taken inside the same serialized transaction as the trim, so a
// revoked device trims nothing and a rejected request observes no state
// content. It is the session counterpart to CompactCRDT; the trimming,
// retained identities, snapshot body and persistence semantics are
// identical.
func (a *App) CompactSessionCRDT(documentID, deviceID string) (crdt.Snapshot, error) {
	return a.crdt.Compact(documentID, deviceID)
}

// GetCRDTSnapshot delegates to the CRDT state service.
func (a *App) GetCRDTSnapshot(documentID string) (crdt.Snapshot, error) {
	return a.crdt.GetSnapshot(documentID)
}

// OpenCRDTSubscription delegates to the CRDT state service.
func (a *App) OpenCRDTSubscription(documentID, deviceID string) (*crdt.State, *crdt.Subscription, func(), error) {
	return a.crdt.OpenSubscription(documentID, deviceID)
}

// AddCRDTSubscription delegates to the CRDT state service.
func (a *App) AddCRDTSubscription(documentID, deviceID string) (*crdt.Subscription, func()) {
	return a.crdt.AddSubscription(documentID, deviceID)
}

// RegisterPush records one freshly established push connection in the
// process-wide in-memory registry. The returned subscription carries the
// server-allocated id and the one-shot active-cancel signal; the connection
// layer removes it when the connection ends.
func (a *App) RegisterPush(deviceID, documentID string, kind push.Kind, cursor int64) *push.Subscription {
	return a.pushSubs.Register(deviceID, documentID, kind, cursor)
}

// UnregisterPush removes an ended push connection.
func (a *App) UnregisterPush(subscriptionID string) {
	a.pushSubs.Unregister(subscriptionID)
}

// ListPushSubscriptions returns the device's live push connections across
// both channels in establishment order. It is a pure memory view.
func (a *App) ListPushSubscriptions(deviceID string) []push.Info {
	return a.pushSubs.List(deviceID)
}

// CancelPushSubscription actively ends one of the device's live push
// connections. It returns false when the id is unknown, already gone, or owned
// by another device; those cases are one indistinguishable 404 at the edge.
func (a *App) CancelPushSubscription(deviceID, subscriptionID string) bool {
	return a.pushSubs.Cancel(deviceID, subscriptionID)
}

// CloseDocumentPush ends every live push connection subscribed to documentID,
// across both channels and every owning device, after its deletion committed.
// Other documents' connections are untouched.
func (a *App) CloseDocumentPush(documentID string) {
	a.pushSubs.CloseDocument(documentID)
}

package server

import (
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// sessionChangeLookupRequest is the body of POST
// .../sessions/{sessionId}/documents/{documentId}/changes/query: only the
// non-empty, in-batch-unique set of change ids travels in the request. The
// calling device is the session's owning device, resolved from the path with
// the same identity rule as the session reads, exports, commits, replays,
// merges, compactions, polls and subscriptions — no new credential is
// introduced. A stray deviceId is decoded and ignored like every other unknown
// field, so it can never override the session owner.
type sessionChangeLookupRequest struct {
	IDs []string `json:"ids"`
}

// handleSessionQueryChanges is the session view's counterpart to the
// document-level read-only batch lookup:
//
//	POST /v1/sessions/{sessionId}/documents/{documentId}/changes/query
//
// The strict application/json body names a non-empty array of non-empty,
// in-batch-unique change ids; answers arrive in the exact order the ids were
// given and use the same changeLookupItem/changeLookupResponse shape the
// document-level lookup emits. Each id is answered independently:
//
//   - "found": the change is still in the online log, so the answer carries
//     its originating device, the payload verbatim as it was saved at commit
//     time and its first cursor;
//   - "compacted": compaction trimmed the row, so the answer reports only the
//     first cursor held in its retained summary — no payload is restored and
//     the summary never participates in an ordinary read;
//   - "missing": the id has never belonged to the document, so the answer
//     carries no content. A missing id is a normal answer, not an error.
//
// Checks run in the fixed order request shape (400) first — content type,
// JSON validity, trailing content, a missing or empty ids array, an empty or
// mistyped element and an in-batch duplicate — then session existence (404)
// and document permission (403). A 404 or 403 exposes no change content. The
// query creates no change, allocates no cursor and wakes neither a long poll
// nor a push subscriber. Success is one compact JSON line ending in a newline
// with results then count.
func handleSessionQueryChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	var req sessionChangeLookupRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	// A missing (nil) or empty ids array is the same request-shape error; a
	// non-string element was already rejected while decoding the JSON.
	if len(req.IDs) == 0 {
		writeError(w, http.StatusBadRequest, "ids must be a non-empty array of non-empty strings")
		return
	}
	seen := make(map[string]struct{}, len(req.IDs))
	for _, id := range req.IDs {
		if id == "" {
			writeError(w, http.StatusBadRequest, "each id must be a non-empty string")
			return
		}
		if _, dup := seen[id]; dup {
			writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+id)
			return
		}
		seen[id] = struct{}{}
	}

	// Request shape is settled; only now does the session lookup run, so a
	// malformed query against an unknown session is still a 400.
	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	// The lookup is the same gated read the document-level batch query uses:
	// the registration/permission verdict is retaken inside its serialized
	// transaction, so a session whose device was deregistered between the two
	// lookups answers 404 and a revoked device answers 403 before any change
	// content is observed.
	lookups, err := s.GetChangesByIDs(documentID, deviceID, req.IDs)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			// The session's device was deregistered between the lookup and the
			// query; its cascade removed the session too, so the identity the
			// caller used no longer exists.
			writeError(w, http.StatusNotFound, "session not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		default:
			writeError(w, http.StatusInternalServerError, "failed to look up changes")
		}
		return
	}

	items := make([]changeLookupItem, len(lookups))
	for i, l := range lookups {
		items[i] = changeLookupItem{
			ID:       l.ID,
			Status:   l.Status,
			DeviceID: l.DeviceID,
			Payload:  l.Payload,
			Cursor:   l.Cursor,
		}
	}
	writeJSON(w, http.StatusOK, changeLookupResponse{Results: items, Count: len(items)})
}

// malformedSessionQueryPath reports whether p targets the session-scoped
// change-log batch lookup but is not at its exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes/query): a missing
// "documents"/"changes" segment, an extra segment, a trailing slash (an empty
// trailing segment), or a "query" segment in a position short of the
// registered shape. ServeMux would answer those with a redirect or a
// plain-text 404/405; every failure of this endpoint must be a JSON 400
// instead and never a redirect. Empty segments are already rejected by the
// guard itself.
//
// "query" is treated as the endpoint keyword only in its terminal segment
// position (the fifth segment, index 4); a session or document identifier
// literally named "query" occupies an identifier position (index 0 or 2) and
// keeps its ordinary routes.
func malformedSessionQueryPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "query" there is an ordinary identifier, not the
	// changes-query keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	// The named-snapshot-version subtree owns its whole shape verdict; a
	// version name coinciding with "query" is an ordinary identifier there.
	if inSessionSnapshotVersionsSubtree(segs) {
		return false
	}
	for i, seg := range segs {
		if seg != "query" {
			continue
		}
		// Identifier positions: sessionId (0) and documentId (2). A value of
		// "query" there is an ordinary identifier, not the endpoint word.
		if i == 0 || i == 2 {
			continue
		}
		// Endpoint keyword position: the fifth segment must be exactly "query"
		// with the documents/changes scaffolding around it, and no segment may
		// follow. Any other occurrence is a malformed path.
		if i == 4 && len(segs) == 5 &&
			segs[0] != "" &&
			segs[1] == "documents" &&
			segs[2] != "" &&
			segs[3] == "changes" {
			return false
		}
		return true
	}
	return false
}

package events

import (
	"database/sql"
	"encoding/json"
	"errors"
)

// Lookup statuses reported per queried id.
const (
	// LookupFound names an id whose change is still in the online log.
	LookupFound = "found"
	// LookupMissing names an id the document has never held a row or a
	// retained summary for.
	LookupMissing = "missing"
	// LookupCompacted names an id whose online row was trimmed by
	// compaction; only its retained summary survives.
	LookupCompacted = "compacted"
)

// ChangeLookup is the answer for one id of a GetChangesByIDs batch, in the
// batch's request order. Status is LookupFound, LookupMissing or
// LookupCompacted.
//
// A found answer carries the online row's originating device, the payload
// exactly as it was stored at commit time and the cursor it was first
// assigned. A compacted answer carries only that first cursor from the
// retained summary — DeviceID and Payload are left empty and never restored.
// A missing answer carries nothing but the id and its status.
type ChangeLookup struct {
	ID       string
	Status   string
	DeviceID string
	Payload  json.RawMessage
	Cursor   int64
}

// GetChangesByIDs answers a read-only batch lookup of change ids for
// documentID in exactly the order given. The gate (registration then
// permission) is taken first inside one serialized transaction — an
// unregistered device yields store.ErrDeviceNotFound and a revoked device
// store.ErrPermissionDenied, before any change content is observed. Then each
// id is answered independently:
//
//   - an id with an online row is LookupFound with its device, verbatim
//     stored payload and first cursor;
//   - an id whose row compaction trimmed is LookupCompacted, reporting only
//     the first cursor held in its retained summary — no payload is restored
//     and the summary takes no part in any read other than this verdict;
//   - any other id (one the document has never known, an unknown document
//     included) is LookupMissing.
//
// Ids may repeat positionally in the answer only when the caller supplied
// them repeatedly; the HTTP layer rejects in-batch duplicates before this
// runs. The read starts a transaction but writes nothing, allocates no
// cursor, creates no change and notifies no waiter or subscriber, so it
// cannot move a cursor or wake a parked poll. The verdicts derive solely from
// durable rows and are therefore byte-stable across a process restart.
func (s *Service) GetChangesByIDs(documentID, deviceID string, ids []string) ([]ChangeLookup, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first, exactly as the gated reads do: the device row and the
	// permission row are read before any change id is observed, so a rejected
	// query cannot reveal content.
	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return nil, err
	}

	out := make([]ChangeLookup, len(ids))
	for i, id := range ids {
		out[i] = ChangeLookup{ID: id, Status: LookupMissing}

		var device string
		var payload []byte
		var cursor int64
		err := tx.QueryRow(
			`SELECT device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND id = ?`,
			documentID, id,
		).Scan(&device, &payload, &cursor)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// No online row: a compaction-trimmed id keeps a retained summary
			// that still records its first cursor. Anything else never existed.
			var trimmedCursor int64
			err := tx.QueryRow(
				`SELECT cursor FROM change_identities
				 WHERE document_id = ? AND id = ?`,
				documentID, id,
			).Scan(&trimmedCursor)
			switch {
			case errors.Is(err, sql.ErrNoRows):
				// Stays LookupMissing with a zero value.
			case err != nil:
				return nil, err
			default:
				out[i] = ChangeLookup{
					ID:     id,
					Status: LookupCompacted,
					Cursor: trimmedCursor,
				}
			}
		case err != nil:
			return nil, err
		default:
			out[i] = ChangeLookup{
				ID:       id,
				Status:   LookupFound,
				DeviceID: device,
				Payload:  json.RawMessage(payload),
				Cursor:   cursor,
			}
		}
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

