		done <- struct {
			changes  int
			timedOut bool
			err      error
		}{len(changes), timedOut, err}
	}()

	time.Sleep(30 * time.Millisecond) // let the poll park
	for i := 0; i < 3; i++ {
		if w := queryChanges(t, h, "doc1", `{"deviceId":"dev","ids":["a","missing"]}`); w.Code != http.StatusOK {
			t.Fatalf("query %d = %d %s", i, w.Code, w.Body.String())
		}
	}

	got := <-done
	if got.err != nil {
		t.Fatalf("poll: %v", got.err)
	}
	if !got.timedOut || got.changes != 0 {
		t.Fatalf("poll woken by a read-only query: %+v", got)
	}

	// The queries consumed no cursor: the next commit gets cursor 2.
	postRawChanges(t, h, "doc1", "dev", `[{"id":"b","payload":2}]`)
	rows, next, err := s.ListChanges("doc1", 0, 100)
	if err != nil {
		t.Fatal(err)
	}
	if len(rows) != 2 || next != 2 || rows[1].Cursor != 2 {
		t.Fatalf("query moved the cursor: rows=%+v next=%d", rows, next)
	}
}

// Method and path shape: only POST at the exact .../changes/query location is
// accepted; every other verb or shape is a JSON 400, never a redirect.
func TestQueryChangesHTTPMethodAndPath(t *testing.T) {
	h, _ := newTestHandler(t)

	cases := []struct {
		method string
		path   string
	}{
		{http.MethodGet, "/v1/documents/doc1/changes/query"},
		{http.MethodPut, "/v1/documents/doc1/changes/query"},
		{http.MethodDelete, "/v1/documents/doc1/changes/query"},
		{http.MethodPost, "/v1/documents/doc1/changes/query/"},
		{http.MethodPost, "/v1/documents/doc1/changes/query/extra"},
		{http.MethodPost, "/v1/documents/doc1/changes/queryextra"},
		{http.MethodPost, "/v1/documents//changes/query"},
		{http.MethodPost, "/v1/documents/doc1/changesx/query"},
	}
	for _, tc := range cases {
		t.Run(tc.method+" "+tc.path, func(t *testing.T) {
			r := httptest.NewRequest(tc.method, tc.path, strings.NewReader(`{"deviceId":"dev","ids":["a"]}`))
			r.Header.Set("Content-Type", "application/json")
			w := httptest.NewRecorder()
			h.ServeHTTP(w, r)
			if w.Code != http.StatusBadRequest {
				t.Fatalf("status = %d want 400 body = %s", w.Code, w.Body.String())
			}
			if ct := w.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
				t.Fatalf("content type = %q, want JSON", ct)
			}
			if loc := w.Header().Get("Location"); loc != "" {
				t.Fatalf("failure redirected to %q", loc)
			}
		})
	}
}

// A document literally named "query" keeps its ordinary change routes; the
// query keyword is only recognized in the terminal subresource position.
func TestQueryChangesHTTPDocumentNamedQuery(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev")
	postRawChanges(t, h, "query", "dev", `[{"id":"z","payload":1}]`)

	// Ordinary paged read on the document named "query".
	w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/query/changes")
	if w.Code != http.StatusOK || !strings.Contains(w.Body.String(), `"id":"z"`) {
		t.Fatalf("paged read on doc named query = %d %s", w.Code, w.Body.String())
	}
	// The lookup subresource of that document answers normally too.
	w = queryChanges(t, h, "query", `{"deviceId":"dev","ids":["z"]}`)
	if w.Code != http.StatusOK || !strings.Contains(w.Body.String(), `"status":"found"`) {
		t.Fatalf("query on doc named query = %d %s", w.Code, w.Body.String())
	}
}

// The query verdict derives solely from durable data: after a process
// restart the same request yields the byte-identical body, including found,
// missing and compacted answers.
func TestQueryChangesHTTPRestartStable(t *testing.T) {
	dir := t.TempDir()
	dbPath := filepath.Join(dir, "sync.db")

	st, err := app.Open(dbPath)
	if err != nil {
		t.Fatal(err)
	}
	h := NewHandler(st)
	registerDevice(t, h, "dev-1")
	postDocChanges(t, h, "doc", "dev-1", 3)
	if w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 1, "state": map[string]any{"s": 1}}); w.Code != http.StatusOK {
		t.Fatal(w.Body.String())
	}
	if w := compactChanges(t, h, "doc", "dev-1"); w.Code != http.StatusOK {
		t.Fatal(w.Body.String())
	}
	body := queryChanges(t, h, "doc", `{"deviceId":"dev-1","ids":["c1","c2","nope"]}`).Body.String()
	if err := st.Close(); err != nil {
		t.Fatal(err)
	}

	st2, err := app.Open(dbPath)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = st2.Close() }()
	h2 := NewHandler(st2)
	r := httptest.NewRequest(http.MethodPost, "/v1/documents/doc/changes/query", strings.NewReader(`{"deviceId":"dev-1","ids":["c1","c2","nope"]}`))
	r.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()
	h2.ServeHTTP(w, r)
	if w.Code != http.StatusOK {
		t.Fatalf("after restart = %d %s", w.Code, w.Body.String())
	}
	if w.Body.String() != body {
		t.Fatalf("body changed across restart:\nbefore %q\nafter  %q", body, w.Body.String())
	}
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strconv"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// crdtCompactRequest is the body of POST .../crdt/compact.
type crdtCompactRequest struct {
	DeviceID string `json:"deviceId"`
}

// handleCRDTCompact trims the document's stored CRDT operations and
// tombstones down to the ones still participating in the merge.
//
// The request contract matches the CRDT submission endpoint: strict
// application/json, exactly one JSON value, no trailing content and a
// non-empty deviceId — any violation is a 400 JSON error with zero writes.
// The device gate then applies in the submission's order: an unregistered
// device is a 404, a device whose permission for the document was revoked is
// a 403, and a document with no committed CRDT operation is a 404; none of
// them writes anything or leaks state content.
//
// On success the answer is 200 with the post-compaction snapshot, rendered
// byte-for-byte like a snapshot read immediately afterward (writeCRDTSnapshot).
// Compaction is idempotent — a repeat trims nothing and returns the same
// body — and touches only the CRDT state layer: it allocates no change
// cursor, writes no change record and, because the merged value never moves,
// pushes no notification.
func handleCRDTCompact(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req crdtCompactRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}

	snapshot, err := s.CompactCRDT(documentID, req.DeviceID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.Is(err, crdt.ErrNotFound):
			writeError(w, http.StatusNotFound, "crdt state not found")
		default:
			writeError(w, http.StatusInternalServerError, "failed to compact crdt state")
		}
		return
	}

	writeCRDTSnapshot(w, snapshot)
}

// handleCRDTSnapshot returns the document's merged CRDT state together with
// the number of stored operations and tombstones the merge is derived from.
// The read carries no device identity and adds no authentication: like the
// document-level state read it is open, and a document with no committed CRDT
// operation answers the same 404 JSON as the state read. The read is pure —
// no cursor, no change record, no subscription.
func handleCRDTSnapshot(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	snapshot, err := s.GetCRDTSnapshot(documentID)
	if err != nil {
		if errors.Is(err, crdt.ErrNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt snapshot")
		return
	}

	writeCRDTSnapshot(w, snapshot)
}

// writeCRDTSnapshot renders a CRDT snapshot exactly as both snapshot surfaces
// must emit it: compact single-line JSON with the keys in type, value,
// operations, tombstones order, terminated by a newline, so the compaction
// response and the snapshot read can be compared byte-for-byte.
func writeCRDTSnapshot(w http.ResponseWriter, snapshot crdt.Snapshot) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(marshalCRDTSnapshot(snapshot))
}

// marshalCRDTSnapshot encodes a CRDT snapshot the single way both surfaces
// emit it: compact single-line JSON with the keys in type, value, operations,
// tombstones order and one trailing newline. The merged value is embedded as
// native JSON (a number, an array, or a register's arbitrary JSON value)
// rather than an escaped blob, and the two counts are non-negative integers.
// The key order is fixed by construction — not by the encoder's map ordering
// — so the bytes are stable across every reader.
func marshalCRDTSnapshot(snapshot crdt.Snapshot) []byte {
	var buf strings.Builder
	typeRaw, _ := json.Marshal(snapshot.Type)
	buf.WriteString(`{"type":`)
	_, _ = buf.Write(typeRaw)
	buf.WriteString(`,"value":`)
	_, _ = buf.Write(snapshot.Value)
	buf.WriteString(`,"operations":`)
	buf.WriteString(strconv.FormatInt(snapshot.Operations, 10))
	buf.WriteString(`,"tombstones":`)
	buf.WriteString(strconv.FormatInt(snapshot.Tombstones, 10))
	buf.WriteString("}\n")
	return []byte(buf.String())
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// handleSessionCRDTCompact is the session-scoped CRDT compaction entry,
// mounted one segment below the session document's CRDT namespace:
//
//	POST /v1/sessions/{sessionId}/documents/{documentId}/crdt/compact
//
// It is the session view's counterpart to
// POST /v1/documents/{documentID}/crdt/compact and shares its trimming,
// idempotency, snapshot-body and persistence semantics byte-for-byte; only
// the caller identity differs. The calling device is the session's owning
// device, resolved from the path with the same identity rule as the session
// reads, commits and subscriptions — no new credential is introduced. The
// body carries no device field: a stray deviceId is decoded and ignored like
// every other unknown field, so it can never override the session owner. The
// body only has to be one legal JSON value — an object, array, scalar or
// null all compact identically; its content never affects the trim.
//
// Checks run in the fixed order request shape (400), session existence
// (404), document permission (403, taken inside the compaction transaction)
// and CRDT state existence (404 for a document with no committed CRDT
// operation). Every rejection writes nothing and observes no state content.
// On success the answer is 200 with the post-compaction snapshot, rendered
// byte-for-byte like the document-level CRDT snapshot read
// (writeCRDTSnapshot): compact single-line JSON with the keys in type,
// value, operations, tombstones order and one trailing newline. Compaction
// is idempotent — a repeat trims nothing and returns the same body — and
// touches only the CRDT state layer: it allocates no change cursor, writes
// no change record and, because the merged value never moves, wakes no
// waiter and pushes no notification.
func handleSessionCRDTCompact(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// The body carries no meaningful field: it only has to be exactly one
	// legal JSON value. Decoding into a RawMessage accepts an object, array,
	// scalar or null, while a missing/empty body, malformed JSON, trailing
	// content or a wrong Content-Type still fail the strict shared decoder.
	var body json.RawMessage
	if !decodeJSONBody(w, r, &body) {
		return
	}

	// Request shape is settled; only now does the session lookup run, so a
	// malformed body against an unknown session is still a 400.
	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	snapshot, err := s.CompactSessionCRDT(documentID, deviceID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			// The session's device was deregistered between the lookup and the
			// compaction; its cascade removed the session too, so the identity
			// the caller used no longer exists.
			writeError(w, http.StatusNotFound, "session not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.Is(err, crdt.ErrNotFound):
			writeError(w, http.StatusNotFound, "crdt state not found")
		default:
			writeError(w, http.StatusInternalServerError, "failed to compact crdt state")
		}
		return
	}

	writeCRDTSnapshot(w, snapshot)
}

