			g := got[i]
			if g.ID != w.id || g.Status != w.status || g.DeviceID != w.device || g.Type != w.kind {
				t.Fatalf("%s[%d] = %+v, want id=%s status=%s device=%s type=%s", tc.doc, i, g, w.id, w.status, w.device, w.kind)
