// writeCRDTLookupError maps a GetCRDTOpsByIDs failure to its fixed JSON
// verdict: a revoked permission is a 403, a document with no committed CRDT
// operation the same 404 the state read gives, and anything else a 500. The
// unregistered-device 404 is worded by the caller (the session view answers
// "session not found" there).
func writeCRDTLookupError(w http.ResponseWriter, err error) {
